#if UNITY_EDITOR
using UnityEngine;using UnityEngine.AI;using UnityEditor;using UnityEditor.SceneManagement;using System.IO;using System.Linq;
namespace DeliveryService.Mok.Editor {
[InitializeOnLoad] static class PrisonDuelIntroductionSetup {
 static PrisonDuelIntroductionSetup(){EditorApplication.update+=Poll;}
 static bool Floor(Vector3 query,out Vector3 point){point=query;if(!NavMesh.SamplePosition(query,out var n,.55f,NavMesh.AllAreas)||Mathf.Abs(n.position.y-query.y)>.4f)return false;point=n.position;return !Physics.OverlapCapsule(point+Vector3.up*.42f,point+Vector3.up*1.55f,.32f,~0,QueryTriggerInteraction.Ignore).Any(c=>!c.GetComponentInParent<Animator>()&&!c.GetComponentInParent<PlayerCombat>());}
 static bool ClearCamera(Vector3 eye,Vector3 focus){return !Physics.Linecast(eye,focus, out var hit,~0,QueryTriggerInteraction.Ignore)||hit.collider.GetComponentInParent<Animator>();}
 static void Poll(){if(EditorApplication.isPlayingOrWillChangePlaymode||EditorApplication.isCompiling||!File.Exists("Temp/PrisonDuelIntroductionSetup"))return;File.Delete("Temp/PrisonDuelIntroductionSetup");try{Build();}catch(System.Exception e){File.WriteAllText("Logs/Prison-duel-introduction-setup.txt",e.ToString());}}
 static void Build(){var scene=EditorSceneManager.GetActiveScene();if(scene.name!="PrisonChapter")return;var d=Object.FindFirstObjectByType<PrisonMedicineDuel>();if(d.introduction){if(!EditorSceneManager.SaveScene(scene,"Logs/Prison-before-intro-camera-"+System.DateTime.Now.ToString("yyyyMMdd-HHmmss")+".unity",true))return;var i=d.introduction;Vector3 eye=i.heraldMark.position+i.heraldMark.forward*1.4f+i.heraldMark.right*1.3f+Vector3.up*1.6f;if(ClearCamera(eye,i.heraldMark.position+Vector3.up*1.4f)){i.heraldCamera.position=eye;i.heraldCamera.LookAt(i.heraldMark.position+Vector3.up*1.4f);}EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);return;}if(!EditorSceneManager.SaveScene(scene,"Logs/Prison-before-duel-intro-"+System.DateTime.Now.ToString("yyyyMMdd-HHmmss")+".unity",true))throw new System.Exception("Backup failed");Physics.SyncTransforms();
 Vector3 home=d.boss.position,best=Vector3.zero,p=Vector3.zero,m=Vector3.zero,h=Vector3.zero,cam=Vector3.zero;Quaternion heading=Quaternion.identity;float cost=float.MaxValue;
 for(float x=-4;x<=4;x+=.8f)for(float z=-4;z<=4;z+=.8f)for(int a=0;a<8;a++){var q=Quaternion.Euler(0,a*45,0);if(!Floor(home+new Vector3(x,0,z),out var b)||!Floor(b+q*new Vector3(-.65f,0,1.7f),out var pp)||!Floor(b+q*new Vector3(.75f,0,1.65f),out var mm)||!Floor(b+q*new Vector3(-2,0,.4f),out var hh))continue;var eye=b+q*new Vector3(2.6f,1.7f,2.6f);if(!ClearCamera(eye,b+Vector3.up*1.3f)||!ClearCamera(eye,pp+Vector3.up*1.3f)||!ClearCamera(eye,mm+Vector3.up*1.3f))continue;float c=x*x+z*z;if(c>=cost)continue;cost=c;best=b;p=pp;m=mm;h=hh;cam=eye;heading=q;}
 if(cost==float.MaxValue)throw new System.Exception("No collision-free conversation layout found; scene unchanged");
 var root=new GameObject("김정민 첫 만남 · 삼자 대화와 소문");root.transform.SetParent(d.transform,false);var intro=root.AddComponent<PrisonDuelIntroduction>();intro.duel=d;d.introduction=intro;
 Transform Mark(string name,Vector3 pos,Vector3 look){var t=new GameObject(name).transform;t.SetParent(root.transform);t.position=pos;t.rotation=Quaternion.LookRotation(look-pos);return t;}
 Vector3 middle=(best+p+m)/3;intro.bossMark=Mark("김정민 대화 위치",best,new Vector3(middle.x,best.y,middle.z));intro.playerMark=Mark("플레이어 대화 위치",p,new Vector3(best.x,p.y,best.z));intro.mingiMark=Mark("민기 대화 위치",m,new Vector3(best.x,m.y,best.z));intro.heraldMark=Mark("소리치는 죄수 위치",h,new Vector3(best.x,h.y,best.z));intro.groupCamera=Mark("삼자 대화 카메라",cam,middle+Vector3.up*1.2f);
 Vector3 heraldEye=h+heading*new Vector3(.5f,1.6f,1.8f);if(!ClearCamera(heraldEye,h+Vector3.up*1.4f))heraldEye=cam;intro.heraldCamera=Mark("싸움 소문 카메라",heraldEye,h+Vector3.up*1.4f);
 GameObject Copy(Transform source,string name){var go=Object.Instantiate(source.gameObject,root.transform);go.name=name;foreach(var script in go.GetComponentsInChildren<MonoBehaviour>(true))Object.DestroyImmediate(script);foreach(var j in go.GetComponentsInChildren<Joint>(true))Object.DestroyImmediate(j);foreach(var rb in go.GetComponentsInChildren<Rigidbody>(true))Object.DestroyImmediate(rb);foreach(var c in go.GetComponentsInChildren<Collider>(true))Object.DestroyImmediate(c);foreach(var agent in go.GetComponentsInChildren<NavMeshAgent>(true))Object.DestroyImmediate(agent);foreach(var r in go.GetComponentsInChildren<Renderer>(true))r.enabled=true;var animator=go.GetComponentInChildren<Animator>(true);animator.enabled=true;animator.runtimeAnimatorController=AssetDatabase.LoadAssetAtPath<RuntimeAnimatorController>("Assets/Scripts/Mok/Art/StoryCharacters/StoryWalk.controller");animator.cullingMode=AnimatorCullingMode.AlwaysAnimate;go.SetActive(false);return go;}
 var player=Copy(d.mission.prison.introduction.mugshotActor,"플레이어 · 죄수복 대화 배우");intro.playerActor=player.transform;intro.playerAnimator=player.GetComponentInChildren<Animator>(true);player.transform.SetPositionAndRotation(p,intro.playerMark.rotation);
 var herald=Copy(d.crowd.GetChild(0),"싸움 소식을 외치는 죄수");intro.herald=herald.transform;intro.heraldAnimator=herald.GetComponentInChildren<Animator>(true);herald.transform.SetPositionAndRotation(h,intro.heraldMark.rotation);
 EditorUtility.SetDirty(d);EditorUtility.SetDirty(intro);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);File.WriteAllText("Logs/Prison-duel-introduction-setup.txt","Saved; all 4 actor capsules clear and on floor. Kim="+best+" player="+p+" Mingi="+m+" herald="+h+" camera="+cam);}
}
}
#endif


